<template>
  <div class="section">
    <img src="../img/appstore_switcher-dark.svg" title="AppStoreSwitcher" alt="AppStoreSwitcher" />
    <br>
    <h2>{{ t('appstore_switcher', 'Switch App Store Source') }}</h2>
    <p>{{ t('appstore_switcher', 'Current App Store:') }} <strong>{{ currentUrl === '' ? t('appstore_switcher', 'Official') + ' (apps.nextcloud.com)' : currentUrl }}</strong></p>

    <div class="store-controls">
      <div class="control-group">
        <h3>{{ t('appstore_switcher', 'Official App Store') }}</h3>
        <button @click="switchToOfficial" :disabled="loading" class="primary">
          {{ t('appstore_switcher', 'Switch to the official App Store') }}
        </button>
      </div>

      <div class="control-group">
        <h3>{{ t('appstore_switcher', 'Custom App Store') }}</h3>

        <div v-if="urlHistory.length > 0" style="margin-bottom: 10px;">
          <label for="url-history">{{ t('appstore_switcher', 'Recently used URLs:') }}</label>
          <div style="display: flex; align-items: center; margin-top: 5px;">
            <select
              id="url-history"
              v-model="selectedHistoryUrl"
              @change="applySelectedUrl"
              style="flex-grow: 1; padding: 8px;"
            >
              <option value="" disabled>{{ t('appstore_switcher', 'Please select...') }}</option>
              <option v-for="(url, index) in urlHistory" :key="index" :value="url">
                {{ url }}
              </option>
            </select>
          </div>

          <br>
          <p><b>{{ t('appstore_switcher', 'Delete App Stores from History:') }}</b></p>
          <ul style="list-style: none; padding: 0; margin-top: 10px; border: 1px solid #ddd; border-radius: 10px;">
            <li v-for="(url, index) in urlHistory" :key="index"
                style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 2px; padding: 4px 8px; border-radius: 4px;">
              <span style="font-size: 0.9em; word-break: break-all;">{{ url }}</span>
              <button
                @click="removeUrl(index, url)"
                :disabled="loading"
                class="icon-delete"
                :title="t('appstore_switcher', 'Remove this URL')">
                <!-- Der Text ist für Screenreader, das Icon kommt per CSS -->
                <span class="hidden-visually">{{ t('appstore_switcher', 'Delete') }}</span>
              </button>
            </li>
          </ul>
        </div>
        <p v-else style="font-size: 0.9em; color: #666; margin-bottom: 10px;">{{ t('appstore_switcher', 'No previous URLs saved.') }}</p>

        <!-- Eingabefeld -->
        <input
          type="text"
          v-model="customUrl"
          :placeholder="t('appstore_switcher', 'https://my-store.de/api/v1')"
          style="width: 100%; margin-bottom: 10px;"
        >

        <button @click="switchToCustom" :disabled="loading" class="primary">
          {{ t('appstore_switcher', 'Switch to Custom App Store') }}
        </button>
      </div>
    </div>

    <p v-if="message" :class="{'error': isError}">{{ message }}</p>
    <p class="hint">{{ t('appstore_switcher', 'Note: After switching, it may take a few minutes for Nextcloud to recognize the chosen app store.') }}</p>
  </div>
</template>

<script>
import { generateUrl } from '@nextcloud/router'
import axios from '@nextcloud/axios'
import { loadState } from '@nextcloud/initial-state'
import { t, n } from '@nextcloud/l10n'

export default {
  name: 'AdminSettings',
  data() {
    return {
      currentUrl: loadState('appstore_switcher', 'current_url'),
      customUrl: loadState('appstore_switcher', 'current_url') || '',
      // Wird nun aus dem PHP Initial State geladen
      urlHistory: loadState('appstore_switcher', 'url_history') || [],
      loading: false,
      message: '',
      isError: false,
      selectedHistoryUrl: ''
    }
  },
  methods: {
    applySelectedUrl() {
      if (this.selectedHistoryUrl) {
        this.customUrl = this.selectedHistoryUrl;
        this.selectedHistoryUrl = '';
      }
    },
    // Async Methode zum Löschen einer URL
    async removeUrl(index, url) {
      this.loading = true;
      try {
        await axios.post(generateUrl('/apps/appstore_switcher/history/remove'), { url: url });
        // Lokales Array aktualisieren
        this.urlHistory.splice(index, 1);
        this.message = 'URL aus Verlauf entfernt';
        this.isError = false;
      } catch (e) {
        this.message = e.response?.data?.msg || 'Fehler beim Löschen';
        this.isError = true;
      } finally {
        this.loading = false;
      }
    },
    async switchToOfficial() {
      this.loading = true
      this.message = ''
      try {
        const response = await axios.post(generateUrl('/apps/appstore_switcher/switch'), { url: 'official' })
        this.message = response.data.msg
        this.currentUrl = ''
        this.customUrl = ''
      } catch (e) {
        this.message = e.response?.data?.msg || 'Fehler beim Umschalten'
        this.isError = true
      } finally {
        this.loading = false
      }
    },
    async switchToCustom() {
      if (!this.customUrl) {
        this.message = 'Bitte eine gültige URL eingeben'
        this.isError = true
        return
      }
      this.loading = true
      this.message = ''
      try {
        // Senden der URL an Backend zum Speichern + Switch
        const response = await axios.post(generateUrl('/apps/appstore_switcher/switch'), { url: this.customUrl })
        this.message = response.data.msg
        this.currentUrl = this.customUrl

        // Lokale Historie aktualisieren (wenn Backend erfolgreich gespeichert hat)
        if (!this.urlHistory.includes(this.customUrl)) {
          this.urlHistory.unshift(this.customUrl);
          //if (this.urlHistory.length > 10) this.urlHistory.pop();
        }
      } catch (e) {
        this.message = e.response?.data?.msg || 'Fehler beim Umschalten'
        this.isError = true
      } finally {
        this.loading = false
      }
    }
  }
}
</script>

<style scoped>
.section { padding: 20px; }
.control-group { margin-bottom: 20px; padding: 15px; border: 1px solid #ddd; border-radius: 5px; }
.error { color: #d93025; font-weight: bold; }
.hint { font-size: 0.9em; color: #666; margin-top: 15px; padding: 15px; border-radius: 5px; background-color: #FCF8E3; }
/* Sicherstellen, dass das Delete-Icon korrekt angezeigt wird */
.icon-delete {
  /* Kein background-image hier definieren! */
  /* Die Klasse 'icon-delete' lädt das Icon automatisch aus dem Nextcloud Core */
  width: 16px;
  height: 16px;
  display: inline-block;
  border: none;
  background-color: transparent;
  cursor: pointer;
  opacity: 0.7;
}

.icon-delete:hover {
  opacity: 1;
}
</style>
